package cli

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const maxBashStartupBytes = 1 << 20

var (
	// Match the shell's source command and its first argument, including the
	// escaped or quoted paths generated by the installer.
	bashSourceLine = regexp.MustCompile(`^(?:(?:builtin|command)[ \t]+)?(?:source|\.)[ \t]+(?:--[ \t]+)?((?:"(?:[^"\\]|\\.)*"|'[^']*'|\\.|[^ \t"'\\;&|()<>#])+)(.*)$`)
	bashSourceEnd  = regexp.MustCompile(`^(?:\|\|[ \t]*(?:(?:return|exit)(?:[ \t]+(?:[0-9]+|\$\?))?|:)[ \t]*)?;?[ \t]*(?:#.*)?$`)
	bashBlockEnd   = regexp.MustCompile(`^(?:fi|done|esac|\}|\))[ \t]*;?[ \t]*(?:#.*)?$`)
)

func (a *app) doctorBashStartup(filter string) {
	// The installer uses --filter missing as its dependency readiness check.
	if filter == "missing" {
		return
	}
	path := os.Getenv("BMCSHELL_BRIDGE_BASHRC")
	if path == "" || !filepath.IsAbs(path) {
		if filter == "" {
			fmt.Fprintln(a.out, "Bash 启动顺序：无法确认（当前命令未提供 ~/.bashrc 路径）")
		}
		return
	}
	info, err := os.Stat(path)
	if err != nil || !info.Mode().IsRegular() || info.Size() > maxBashStartupBytes {
		if filter == "" {
			fmt.Fprintf(a.out, "Bash 启动顺序：无法检查 %s（文件不存在、不是普通文件或超过 1 MiB）\n", path)
		}
		return
	}
	file, err := os.Open(path)
	if err != nil {
		if filter == "" {
			fmt.Fprintf(a.out, "Bash 启动顺序：无法读取 %s\n", path)
		}
		return
	}
	defer file.Close()
	load, following, err := bashStartupOrder(file)
	switch {
	case err != nil:
		if filter == "" {
			fmt.Fprintf(a.out, "Bash 启动顺序：无法完整读取 %s\n", path)
		}
	case load == 0:
		if filter == "" {
			fmt.Fprintf(a.out, "Bash 启动顺序：无法确认（%s 未找到可识别的 BMCShell 加载语句）\n", path)
		}
	case following != 0:
		if filter == "" {
			fmt.Fprintf(a.out, "Bash 启动顺序：%s %s:%d，BMCShell 加载语句之后第 %d 行仍有内容。将加载块移到其他初始化命令之后。\n", outputColor(a.out, outputWarning, "请检查"), path, load, following)
		}
	default:
		fmt.Fprintf(a.out, "Bash 启动顺序：%s（%s:%d，BMCShell 加载块位于文件末尾）\n", outputColor(a.out, outputSuccess, "正常"), path, load)
	}
}

// bashStartupOrder checks recognizable source lines in a single file. It
// never evaluates the file or attempts to resolve nested source commands.
func bashStartupOrder(reader io.Reader) (load, following int, err error) {
	limited := &io.LimitedReader{R: reader, N: maxBashStartupBytes + 1}
	scanner := bufio.NewScanner(limited)
	scanner.Buffer(make([]byte, 4096), maxBashStartupBytes+1)
	for line := 1; scanner.Scan(); line++ {
		text := strings.TrimSpace(scanner.Text())
		if line == 1 {
			text = strings.TrimSpace(strings.TrimPrefix(text, "\uFEFF"))
		}
		if text == "" || strings.HasPrefix(text, "#") || bashBlockEnd.MatchString(text) {
			continue
		}
		if match := bashSourceLine.FindStringSubmatch(text); match != nil {
			target := strings.Trim(match[1], "'\"")
			if target == "bmcshell.sh" || strings.HasSuffix(target, "/bmcshell.sh") ||
				strings.HasSuffix(target, "/.bmcshell-install/load.sh") {
				load, following = line, 0
				if !bashSourceEnd.MatchString(strings.TrimSpace(match[2])) {
					following = line
				}
				continue
			}
		}
		if load != 0 && following == 0 {
			following = line
		}
	}
	if err := scanner.Err(); err != nil {
		return 0, 0, err
	}
	if limited.N == 0 {
		return 0, 0, fmt.Errorf("Bash 启动文件超过 1 MiB")
	}
	return load, following, nil
}
